# END FROZEN RECIPE


def need(condition, message):
    if not condition:
        raise ValueError(message)


def sha(data):
    return hashlib.sha256(data).hexdigest()


def parse_gbl(data):
    """Validate complete TLV framing, exact record inventory, geometry and CRC."""
    records = []
    pos = 0
    while pos < len(data):
        need(pos + 8 <= len(data), 'truncated GBL record header')
        tag, size = struct.unpack_from('<II', data, pos)
        end = pos + 8 + size
        need(end <= len(data), 'truncated GBL record payload')
        records.append((tag, data[pos + 8:end]))
        pos = end
    need(tuple(t for t, _ in records) == TAGS, 'unsupported GBL record inventory/order')
    need([len(v) for _, v in records[:3]] == [8, 28, 25868], 'GBL metadata geometry')
    need(records[0][1] == bytes.fromhex('0000000300000000'), 'GBL header version/flags')
    need(len(records[3][1]) >= 4 and records[3][1][:4] == bytes(4), 'first PROGRAM load address')
    need(len(records[4][1]) == 0x789C, 'second PROGRAM size')
    need(struct.unpack_from('<I', records[4][1])[0] == 0x130A98, 'second PROGRAM load address')
    need(len(records[3][1]) - 4 < 0x130A98, 'overlapping PROGRAM ranges')
    need(len(records[5][1]) == 4, 'END record size')
    need(struct.unpack('<I', records[5][1])[0] == zlib.crc32(data[:-4]), 'GBL END CRC mismatch')
    need(zlib.crc32(data) == RESIDUE, 'GBL CRC residue mismatch')
    return records


def validate_stock(data):
    need(len(data) == STOCK_SIZE, 'unsupported stock GBL size')
    need(sha(data) == STOCK_SHA256, 'unsupported stock GBL SHA256')
    records = parse_gbl(data)
    app = records[3][1][4:]
    need(len(app) == STOCK_APP_SIZE and sha(app) == STOCK_APP_SHA256, 'stock application identity mismatch')
    return records, app


def load_recipe():
    raw = zlib.decompress(base64.b85decode(RECIPE_B85))
    need(sha(raw) == RECIPE_SHA256, 'embedded patch recipe integrity mismatch')
    recipe = json.loads(raw)
    need(len(recipe) == 1404, 'patch recipe record count')
    return recipe


def apply_recipe(stock_app, recipe):
    need(len(stock_app) == STOCK_APP_SIZE and sha(stock_app) == STOCK_APP_SHA256, 'stock application identity mismatch')
    padded = stock_app + b'\xff' * (APP_SIZE - len(stock_app))
    app = bytearray(padded)
    previous_end = 0
    # Verify every preimage before making any changes, including FF extension.
    decoded = []
    for start, end, owner, pre_sha, mask_hex in recipe:
        need(type(start) is int and type(end) is int and previous_end <= start < end <= APP_SIZE,
             'patch geometry/overlap: ' + str(owner))
        mask = bytes.fromhex(mask_hex)
        need(len(mask) == end - start, 'patch length: ' + str(owner))
        need(sha(padded[start:end]) == pre_sha, 'patch preimage mismatch at ' + hex(start))
        decoded.append((start, end, mask))
        previous_end = end
    for start, end, mask in decoded:
        app[start:end] = bytes(x ^ y for x, y in zip(padded[start:end], mask))
    return bytes(app)


def validate_application(app):
    """Final identity validation is independent of the patch recipe."""
    need(len(app) == APP_SIZE, 'output application size mismatch')
    need(sha(app) == APP_SHA256, 'output application SHA256 mismatch')
    need(zlib.crc32(app) == APP_CRC32, 'output application CRC32 mismatch')
    need(sha(app[0xADA20:0xF9E70]) == SEC_SHA256, 'output official WF200 SEC mismatch')
    need(struct.unpack_from('<I', app)[0] == struct.unpack_from('<I', app, 0x254)[0] == 0x2007FF80,
         'output MSP mismatch')


def pack_gbl(records, app):
    out = bytearray()
    for index, (tag, payload) in enumerate(records):
        if index == 3:
            payload = bytes(4) + app
        if index == 5:
            out += struct.pack('<II', tag, 4)
            out += struct.pack('<I', zlib.crc32(out))
        else:
            out += struct.pack('<II', tag, len(payload)) + payload
    return bytes(out)


def validate_output(gbl, stock_records, app):
    """Reparse emitted bytes and compare retained records, then fixed identities."""
    records = parse_gbl(gbl)
    for index in (0, 1, 2, 4):
        need(records[index] == stock_records[index], 'output changed retained GBL record')
    extracted = records[3][1][4:]
    need(extracted == app, 'output PROGRAM extraction mismatch')
    validate_application(extracted)
    need(len(gbl) == GBL_SIZE, 'output GBL size mismatch')
    need(sha(gbl) == GBL_SHA256, 'output GBL SHA256 mismatch')
    need(struct.unpack('<I', records[5][1])[0] == END_CRC32, 'output END CRC mismatch')


def construct(data):
    records, stock_app = validate_stock(data)
    app = apply_recipe(stock_app, load_recipe())
    validate_application(app)
    gbl = pack_gbl(records, app)
    validate_output(gbl, records, app)
    return app, gbl


def write_outputs(directory, app, gbl, records):
    """Exclusive creation; never replace existing files or follow output symlinks.

    Both results are validated before creation, then read back before success.
    On failure remove only files exclusively created by this invocation.
    """
    paths = [directory / (OUTPUT_NAME + suffix) for suffix in ('.bin', '.gbl')]
    need(not any(p.exists() or p.is_symlink() for p in paths), 'output already exists; move it before running again')
    directory.mkdir(parents=True, exist_ok=True)
    created = []
    try:
        for path, payload in zip(paths, (app, gbl)):
            with path.open('xb') as stream:
                created.append(path)
                stream.write(payload)
                stream.flush()
                os.fsync(stream.fileno())
        disk_app, disk_gbl = (p.read_bytes() for p in paths)
        validate_application(disk_app)
        validate_output(disk_gbl, records, disk_app)
    except BaseException:
        for path in created:
            path.unlink()
        raise
    return paths


def main(argv=None):
    parser = argparse.ArgumentParser(description='Offline exact-stock to experimental B2.2 patcher. No flashing or network access.')
    parser.add_argument('input', nargs='?', type=Path, default=TARGET / STOCK_NAME, help='stock GBL (default: script directory/target/' + STOCK_NAME + ')')
    parser.add_argument('--output-dir', type=Path, default=TARGET, help='output directory (default: script directory/target/)')
    args = parser.parse_args(argv)
    try:
        # Bound reads before loading unknown input; revalidate the bytes afterward.
        need(args.input.stat().st_size == STOCK_SIZE, 'unsupported stock GBL size')
        with args.input.open('rb') as stream:
            data = stream.read(STOCK_SIZE + 1)
        app, gbl = construct(data)
        records = parse_gbl(data)
        paths = write_outputs(args.output_dir, app, gbl, records)
    except (OSError, ValueError, TypeError, KeyError, zlib.error, struct.error) as error:
        print('ERROR: ' + str(error), file=sys.stderr)
        return 1
    print('Stock: exact size/SHA256, GBL structure and CRC verified; original preserved.')
    print(f'Application: {len(app)} bytes | SHA256 {sha(app)} | CRC32 {zlib.crc32(app):08X}')
    print(f'GBL: {len(gbl)} bytes | SHA256 {sha(gbl)} | END {END_CRC32:08X} | residue {RESIDUE:08X}')
    print('B2.2 exact qualified identities verified; output readback verified.')
    for path in paths:
        print(path)
    print('EXPERIMENTAL: physical hardware runtime testing is in progress; long-term battery improvement is unproven.')
    return 0


if __name__ == '__main__':
    sys.exit(main())
